  const match = products.find(p => p.name === name);
  return match ? match.id : null;
}

// Helper: find sales order line by product id or name
function findOrderLine(productId, productName) {
  return orderLines.find(l => {
    if (Array.isArray(l.product_id)) {
      return l.product_id[0] === productId || l.product_id[1] === productName;
    }
    return l.product_id === productId;
  }) || null;
}

